/** Max width for Walmart week dropdown menu items */
export declare const WALMART_WEEK_MENU_ITEM_WIDTH = "310px";
/**
 * Minimum number of week options (including section-header rows) required
 * before the search field is shown inside a Walmart week dropdown.
 *
 * Below this threshold a search input adds interaction noise without value
 * and alters focus semantics (initial focus shifts to the text input rather
 * than the active/first option), which breaks expected keyboard and AT flows.
 *
 * The default date window (~65 weeks) comfortably exceeds this threshold, so
 * search is on by default. Tight minDate/maxDate windows that produce short
 * lists will correctly omit it.
 */
export declare const WALMART_WEEK_SEARCH_THRESHOLD = 15;
